TLM.f("Tempora/Quad4-0",{"officium":"Dominica IV in Quadragesima","rule":["no Gloria","Credo","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;"],"sections":{"Introitus":[{"k":"ref","la":"Is 66:10 et 11"},{"k":"text","la":"Lætáre, Jerúsalem: et convéntum fácite, omnes qui dilígitis eam: gaudéte cum lætítia, qui in tristítia fuístis: ut exsultétis, et satiémini ab ubéribus consolatiónis vestræ."},{"k":"ref","la":"Ps 121:1"},{"k":"text","la":"Lætátus sum in his, quæ dicta sunt mihi: in domum Dómini íbimus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Lætáre, Jerúsalem: et convéntum fácite, omnes qui dilígitis eam: gaudéte cum lætítia, qui in tristítia fuístis: ut exsultétis, et satiémini ab ubéribus consolatiónis vestræ."}],"Oratio":[{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut, qui ex mérito nostræ actiónis afflígimur, tuæ grátiæ consolatióne respirémus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Gálatas"},{"k":"ref","la":"Gal 4:22-31"},{"k":"text","la":"Fratres: Scriptum est: Quóniam Abraham duos fílios hábuit: unum de ancílla, et unum de líbera. Sed qui de ancílla, secúndum carnem natus est: qui autem de líbera, per repromissiónem: quæ sunt per allegoríam dicta. Hæc enim sunt duo testaménta. Unum quidem in monte Sina, in servitútem génerans: quæ est Agar: Sina enim mons est in Arábia, qui conjúnctus est ei, quæ nunc est Jerúsalem, et servit cum fíliis suis. Illa autem, quæ sursum est Jerúsalem, líbera est, quæ est mater nostra. Scriptum est enim: Lætáre, stérilis, quæ non paris: erúmpe, et clama, quæ non párturis: quia multi fílii desértæ, magis quam ejus, quæ habet virum. Nos autem, fratres, secúndum Isaac promissiónis fílii sumus. Sed quómodo tunc is, qui secúndum carnem natus fúerat, persequebátur eum, qui secúndum spíritum: ita et nunc. Sed quid dicit Scriptúra? Ejice ancíllam et fílium ejus: non enim heres erit fílius ancíllæ cum fílio líberæ. Itaque, fratres, non sumus ancíllæ fílii, sed líberæ: qua libertáte Christus nos liberávit."}],"Graduale":[{"k":"ref","la":"Ps 121:1, 7"},{"k":"text","la":"Lætátus sum in his, quæ dicta sunt mihi: in domum Dómini íbimus."},{"k":"text","la":"Fiat pax in virtúte tua: et abundántia in túrribus tuis.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 124:1-2"},{"k":"text","la":"Qui confídunt in Dómino, sicut mons Sion: non commovébitur in ætérnum, qui hábitat in Jerúsalem."},{"k":"text","la":"Montes in circúitu ejus: et Dóminus in circúitu pópuli sui, ex hoc nunc et usque in sǽculum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 6:1-15"},{"k":"text","la":"In illo témpore: Abiit Jesus trans mare Galilǽæ, quod est Tiberíadis: et sequebátur eum multitúdo magna, quia vidébant signa, quæ faciébat super his, qui infirmabántur. Súbiit ergo in montem Jesus: et ibi sedébat cum discípulis suis. Erat autem próximum Pascha, dies festus Judæórum. Cum sublevásset ergo óculos Jesus et vidísset, quia multitúdo máxima venit ad eum, dixit ad Philíppum: Unde emémus panes, ut mandúcent hi? Hoc autem dicébat tentans eum: ipse enim sciébat, quid esset factúrus. Respóndit ei Philíppus: Ducentórum denariórum panes non suffíciunt eis, ut unusquísque módicum quid accípiat. Dicit ei unus ex discípulis ejus, Andréas, frater Simónis Petri: Est puer unus hic, qui habet quinque panes hordeáceos et duos pisces: sed hæc quid sunt inter tantos? Dixit ergo Jesus: Fácite hómines discúmbere. Erat autem fænum multum in loco. Discubuérunt ergo viri, número quasi quinque míllia. Accépit ergo Jesus panes, et cum grátias egísset, distríbuit discumbéntibus: simíliter et ex píscibus, quantum volébant. Ut autem impléti sunt, dixit discípulis suis: Collígite quæ superavérunt fragménta, ne péreant. Collegérunt ergo, et implevérunt duódecim cóphinos fragmentórum ex quinque pánibus hordeáceis, quæ superfuérunt his, qui manducáverant. Illi ergo hómines cum vidíssent, quod Jesus fécerat signum, dicébant: Quia hic est vere Prophéta, qui ventúrus est in mundum. Jesus ergo cum cognovísset, quia ventúri essent, ut ráperent eum et fácerent eum regem, fugit íterum in montem ipse solus."}],"Offertorium":[{"k":"ref","la":"Ps 134:3, 6"},{"k":"text","la":"Laudáte Dóminum, quia benígnus est: psállite nómini ejus, quóniam suávis est: ómnia, quæcúmque vóluit, fecit in cœlo et in terra."}],"Secreta":[{"k":"text","la":"Sacrifíciis præséntibus, Dómine, quǽsumus, inténde placátus: ut et devotióni nostræ profíciant et salúti."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 121:3-4"},{"k":"text","la":"Jerúsalem, quæ ædificátur ut cívitas, cujus participátio ejus in idípsum: illuc enim ascendérunt tribus, tribus Dómini, ad confiténdum nómini tuo, Dómine."}],"Postcommunio":[{"k":"text","la":"Da nobis, quǽsumus, miséricors Deus: ut sancta tua, quibus incessánter explémur, sincéris tractémus obséquiis, et fidéli semper mente sumámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"a2ac71d0c2ab0ca2":{"t":"Iz 66, 10-11, Ps 121, 1\n(Iz 66, 10-11) Veseli se, Jeruzaleme! Okupite se svi koji ga ljubite. Radujte se u njegovu veselju svi koji ste s njim bili žalosni. Kličite od radosti i nasitite se svoje utjehe. (Ps 121, 1) Obradovao sam se kad mi rekoše: Idemo u dom Gospodnji.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iz 66, 10-11) Veseli se, Jeruzaleme! Okupite se svi koji ga ljubite. Radujte se u njegovu veselju svi koji ste s njim bili žalosni. Kličite od radosti i nasitite se svoje utjehe."},"b8a04e228df25f2d":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da mi koji zasluženo trpimo zbog svojih djela, odahnemo utješeni tvojom milošću.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"edcbcf5d471cca6a":{"t":"Gal 4, 22-31\nČitanje Poslanice bl. Pavla apostola Galaćanima. Braćo: pisano je da je Abraham imao dva sina: jednoga od ropkinje, a drugoga od slobodne. Onaj od ropkinje rođen je u tijelu, a onaj od slobodne po obećanju. To je u slici rečeno. Te dvije žene znače dva zavjeta: jedan, onaj s gore Sinaja, rađa robove – to je Agara (jer je gora Sinaj u Arabiji) i odgovara današnjem Jeruzalemu koji robuje zajedno sa svojom djecom. A nebeski Jeruzalem slobodan je, i on je naša majka. Pisano je naime: »Veseli se, neplodnice, koja ne rađaš! Kliči i viči, koja ne znaš za porođajne bolove, jer napuštena žena ima mnogo više djece nego ona koja ima muža.« A mi smo, braćo, kao Izak djeca obećanja. Ali, kao što je onda onaj rođeni po tijelu progonio rođenoga po duhu, tako je i sada. Međutim, što zapovijeda Pismo? »Istjeraj ropkinju i njezina sina, jer sin ropkinje neće dijeliti baštine sa sinom slobodne.« Tako, braćo, mi nismo djeca ropkinje, nego slobodne; a tu nam je slobodu Krist darovao."},"4ed8d93c14977e9d":{"t":"Ps 121, 1 i 7\nObradovao sam se kad mi rekoše: »Idemo u dom Gospodnji.« Neka bude mir u tvojim tvrđavama, sigurnost u tvojim kulama.\n\nPs 124, 1-2\nKoji se uzdaju u Gospodina oni su kao gora Sion koja ostaje dovijeka. Tko stanuje u Jeruzalemu neće se pokolebati. Jer kao što gore štite Jeruzalem, tako Gospodin okružuje svoj narod i sada i dovijeka."},"9d0466d0ead7fe3d":{"t":"Iv 6, 1-15\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme: prijeđe Isus na drugu stranu Galilejskog ili Tiberijadskog mora. Za njim je išlo veliko mnoštvo naroda, jer su vidjeli čudesa što ih je činio na bolesnicima. Isus se popne na goru i sjedne ondje sa svojim učenicima. A bio je blizu Vazam, židovski blagdan. – Isus podigne oči i vidi da k njemu dolazi silno mnoštvo naroda, pa upita Filipa: »Gdje ćemo kupiti kruha da ovi jedu?« Ovo reče da bi ga kušao, jer je znao što će učiniti. Filip mu odgovori: »Dvjesta dinara kruha nije dosta da svaki malo dobije.« Jedan od njegovih učenika, Andrija, brat Šimuna Petra, reče: »Jedan je dječak ovdje koji ima pet ječmenih hljebova i dvije ribe. Ali, što je to za toliki svijet!« – Isus im zapovjedi: »Recite ljudima da sjednu.« A bilo je ondje mnogo trave. I posjedalo je oko pet tisuća ljudi. Isus tada uze kruh, zahvali (Bogu) i razdijeli prisutnima. Tako i od riba, koliko su htjeli. Kad su se nasitili, reče svojim učenicima: »Sakupite komade što su pretekli, da ne propadnu!« I skupe ih, i napune dvanaest košara komada što su pretekli onima koji su jeli od pet ječmenih hljebova. Kad ljudi vidješe čudo koje učini Isus, rekoše: »Ovo je zaista prorok koji ima doći na svijet.« A kad je Isus razumio da namjeravaju doći, da ga uhvate i proglase kraljem, ponovo otiđe sam u goru.","v":"naslov evanđelja"},"2f6ac6679888fff0":{"t":"Ps 134, 3 i 6\nHvalite Gospodina, jer je dobar. Pjevajte njegovu imenu, jer je ljubak. Sve što hoće, čini na nebu i na zemlji."},"90a1614471aa68a1":{"t":"Umilostivljen pogledaj, molimo, Gospodine, na ove žrtve, da koriste i našoj pobožnosti i spasenju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"0aae9786270c1669":{"t":"Ps 121, 3-4\nJeruzalem je sagrađen kao grad sav u jednom sklopu. Onamo ulaze plemena, Gospodnja plemena, da slave tvoje ime Gospodine."},"b8d4302d9a23fb0b":{"t":"<i>Pomolimo se</i>.\nDaj nam, molimo, milosrdni Bože, da sveta otajstva, kojima se neprestano hranimo, iskreno poštujemo i uvijek ih vjerna srca primamo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
